public class PriceCalculator { public static double getBasePrice(String event,String pkg){return FeeManager.getPrice(event,pkg);} public static double calculateDiscount(double amount,double percent){return amount*percent/100.0;} public static double calculateFinalPrice(double amount,double percent){return amount-calculateDiscount(amount,percent);} public static void printPriceBreakdown(double base,double percent){double discount=calculateDiscount(base,percent);System.out.println("\n========== PRICE BREAKDOWN ==========");System.out.printf("Base Price : Rs. %.2f%nDiscount   : Rs. %.2f (%.1f%%)%nFinal Price: Rs. %.2f%n",base,discount,percent,base-discount);System.out.println("=====================================");} }
